def pbUpdate(fullChange = false)
  return if !@pokemon
  @pokemon.calc_stats
  @level          = @pokemon.level
  @hp             = @pokemon.hp
  @totalhp        = @pokemon.totalhp
  if !@effects[PBEffects::Transform]
    @attack       = @pokemon.attack
    @defense      = @pokemon.defense
    @spatk        = @pokemon.spatk
    @spdef        = @pokemon.spdef
    @speed        = @pokemon.speed
    if fullChange
      @types      = @pokemon.types
      @ability_id = @pokemon.ability_id
    end
  end
end
